// guardado-fiel · REQ-SAVE1 · un guardado que el servidor RECHAZA deja de contar como guardado.
//
// EL FALLO, en `web/app.js:22364` (`mcSaveWorldFull`), tal cual está hoy:
//
//     try{ await fetch(mcWorldUrl(), {method:'POST', …, body:JSON.stringify(mcSerialize())}); }
//     catch(e){ toast('No se pudo guardar el mundo'); return false; }
//     mc.v2=true;                          // ← se da por escrito
//     if(mc.pend){ …; mc.pend.vox.clear(); } // ← y se TIRA lo que quedaba por guardar
//     return true;                         // ← y se le dice «hecho» a quien preguntó
//
// `fetch` sólo tira una excepción si la petición no llega a completarse: un corte de red, un CORS.
// Un 401, un 403 o un 500 son respuestas PERFECTAMENTE NORMALES y no entran por el `catch`. O sea:
// el servidor dice que no, y el motor marca el mundo como guardado, vacía el conjunto de pendientes
// —que es la única memoria de lo que faltaba por escribir— y devuelve `true`. El jugador construye
// una tarde entera contra un servidor que le rechaza cada POST y no se entera hasta que recarga.
//
// Y no es un caso de laboratorio: con `VOXELFORGE_PUBLICO=1`, un 403 al guardar un mapa que no es
// tuyo es la respuesta ESPERADA. Su hermana `mcSaveWorldAhora` sí mira `r.ok` en sus dos ramas
// (`app.js:22344` y `:22351`) y reintenta; la asimetría entre las dos ES el bug.
//
// ── LEY DE ORO ──────────────────────────────────────────────────────────────────────────────────
// Esto vive aquí y NO en `app.js` hasta que ruede. Se sustituye `window.mcSaveWorldFull` guardando
// el original en `_orig`, y `game.guardado.off()` lo devuelve byte a byte. Las tres referencias
// internas del motor (`return mcSaveWorldFull()` en `app.js:22322`, `:22343` y `:22350`) son
// lecturas de una propiedad del objeto global, así que pasan por el envoltorio sin tocar nada.
//
//     game.guardado.estado()   → qué hay puesto y cuántos rechazos se han visto
//     game.guardado.off()      → devuelve el motor
//
// Cuando se gradúe a `app.js` serán DOS líneas: recoger la respuesta en `const r` y
// `if(!r.ok){ toast(…); return false; }` antes del `mc.v2=true`.

(function () {
  const VERSION = 'v2';

  // Ya puesto y de esta misma versión: no se apila un envoltorio sobre otro (dos capas harían dos
  // avisos por fallo y `off()` dejaría el de dentro colgado).
  if (window.mcSaveWorldFull && window.mcSaveWorldFull._fiel === VERSION) {
    console.log('[guardado-fiel] ' + VERSION + ' ya estaba puesto.');
    return;
  }

  const orig = (window.mcSaveWorldFull && window.mcSaveWorldFull._fiel)
    ? window.mcSaveWorldFull._orig          // había una versión vieja: se parte del motor de verdad
    : window.mcSaveWorldFull;

  if (typeof orig !== 'function') {
    console.warn('[guardado-fiel] no encuentro `mcSaveWorldFull`: no toco nada.');
    return;
  }

  let rechazos = 0;
  let ultimo = null;

  async function mcSaveWorldFullFiel() {
    // ⛔ BUG-SAVE2 · LA INSTANTÁNEA Y LA BANDERA VAN JUNTAS, Y ANTES DEL `await`.
    //
    // `mcSerialize()` es SÍNCRONO: lo que devuelve es el mundo exacto de este instante, y a partir
    // de aquí cualquier escritura es POSTERIOR y este POST ya no la lleva. El motor bajaba `p.full`
    // al SALIR (app.js:22460), y mientras está puesta `mcDirty` se va sin apuntar nada
    // (app.js:9045) — así que todo lo escrito durante el viaje (segundos, con 13 MB por delante) no
    // iba en la instantánea NI quedaba apuntado, y el `vox.clear()` del final borraba el último
    // rastro. En pantalla seguía viéndose; en disco no estaba. Eso es la playa sin agua del dueño.
    //
    // Bajándola aquí, esas escrituras vuelven a pasar por `mcDirty` y se acumulan solas en `p.vox`,
    // que es lo que el siguiente ciclo mandará por `/edits`. Misma disciplina que ya usa el camino
    // incremental en `mcSaveWorldAhora` (app.js:22416); la asimetría entre los dos ERA el bug.
    const _pend = mc.pend;
    const _cuerpo = JSON.stringify(mcSerialize());
    // Lo apuntado se SACA (no se borra) y se pone un Set nuevo en su sitio: es letra por letra lo que
    // hace el camino incremental en `mcSaveWorldAhora` (app.js:22419), y por el mismo motivo — si el
    // viaje sale mal hay que poder devolverlo.
    const _antes = _pend ? _pend.vox : null;
    if (_pend) { _pend.vox = new Set(); _pend.full = false; _pend.header = false; }
    // Si el POST no sale bien no se sabe qué llegó: se vuelve al mundo entero Y se devuelve lo que se
    // había sacado, como el `devolver()` de al lado. Perder un viaje es barato; perder voxels, no.
    const _rendirse = function () {
      if (!_pend) return;
      _pend.full = true; _pend.header = true;
      for (const k of _antes) _pend.vox.add(k);
    };

    let r;
    try {
      r = await fetch(mcWorldUrl(), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: _cuerpo
      });
    } catch (e) {
      // Sin cambios respecto al motor: esto es el corte de red de siempre.
      _rendirse();
      toast('No se pudo guardar el mundo');
      return false;
    }

    // ⛔ LA LÍNEA QUE FALTABA. Y se sale ANTES de tocar `mc.v2` y `mc.pend`: dejar el pendiente
    // intacto es lo que permite que el siguiente ciclo lo reintente con lo acumulado entre medias,
    // exactamente como hace `devolver()` en `mcSaveWorldAhora`.
    if (!r.ok) {
      _rendirse();
      rechazos++;
      ultimo = r.status;
      const porque = (r.status === 401 || r.status === 403)
        ? 'este mapa no es tuyo o no has entrado'
        : 'el servidor respondió ' + r.status;
      console.warn('[guardado-fiel] el mundo NO se ha guardado: ' + porque +
                   ' — lo pendiente se conserva y se reintenta.');
      toast('No se pudo guardar el mundo: ' + porque, 5);
      return false;
    }

    mc.v2 = true;                                            // el servidor siempre lo escribe en v2
    // ⛔ Y AQUÍ YA NO SE VACÍA `p.vox`. Lo que contiene es lo escrito DESPUÉS de la instantánea, o
    // sea exactamente lo que este POST no lleva; tirarlo era la segunda mitad de BUG-SAVE2. Las
    // banderas ya se bajaron arriba, así que no hay nada que bajar.
    return true;
  }

  mcSaveWorldFullFiel._fiel = VERSION;
  mcSaveWorldFullFiel._orig = orig;
  window.mcSaveWorldFull = mcSaveWorldFullFiel;

  game.guardado = {
    on: function () {
      if (window.mcSaveWorldFull._fiel !== VERSION) window.mcSaveWorldFull = mcSaveWorldFullFiel;
      return game.guardado.estado();
    },
    off: function () {
      // Byte a byte: se devuelve el original que se guardó, no una copia parecida.
      if (window.mcSaveWorldFull && window.mcSaveWorldFull._fiel) window.mcSaveWorldFull = orig;
      return 'guardado-fiel apagado; `mcSaveWorldFull` es otra vez el del motor.';
    },
    estado: function () {
      const puesto = !!(window.mcSaveWorldFull && window.mcSaveWorldFull._fiel);
      return { version: VERSION, puesto: puesto, rechazos: rechazos, ultimoCodigo: ultimo };
    }
  };

  console.log('[guardado-fiel] ' + VERSION + ' puesto · `mcSaveWorldFull` ya mira `r.ok`. ' +
              'game.guardado.estado() / .off()');
})();
